package com.example.spring_blog.interceptor;import com.example.spring_blog.error.Exception403;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import org.jspecify.annotations.Nullable;import org.springframework.stereotype.Component;import org.springframework.web.servlet.HandlerInterceptor;import org.springframework.web.servlet.ModelAndView;// 특정 IP를 차단하는 인터셉터를 구현@Componentpublic class IpBlockInterceptor implements HandlerInterceptor {    @Override    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception {        String clientIp = request.getRemoteAddr(); // 접속한 ip주소 확인        String allowedIp = "192.168.7.51";        if (!allowedIp.equals(clientIp)) {            throw new Exception403("허용되지않은 IP 주소입니다.");        }        return true;    }    @Override    public void postHandle(HttpServletRequest request, HttpServletResponse response, Object handler, @Nullable ModelAndView modelAndView) throws Exception {        HandlerInterceptor.super.postHandle(request, response, handler, modelAndView);    }    @Override    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, @Nullable Exception ex) throws Exception {        HandlerInterceptor.super.afterCompletion(request, response, handler, ex);    }}